  "Every 30 minutes": "كل 30 دقيقة", "Every hour": "كل ساعة", "Every 2 hours": "كل ساعتين", "Air times": "مواعيد البث", "Like Windows": "مثل إعداد Windows",
  "24-hour (18:30)": "نظام 24 ساعة (18:30)", "12-hour (6:30 PM)": "نظام 12 ساعة (6:30 م)", "Cleanup": "التنظيف",
